const findSoldiersWithRank = (soldiers, monthSchedules, day, labels) => {
    return soldiers.filter(s => {
        const cellLabels = monthSchedules[s.id]?.[day] || [];
        return labels.some(l => cellLabels.includes(l));
    }).map(s => `${s.rank} ${s.name}`);
};

